<template><view class="page"><AppHeader/><view class="content">
  <template v-if="remoteBlocks.length">
    <view v-for="block in remoteBlocks" :key="block.id" class="remote-block">
      <view v-if="block.type==='banner'" class="hero"><image :src="block.image" mode="aspectFill"/><view class="hero-mask"><view class="tag tag-orange">{{block.badge||'精选推荐'}}</view><view class="hero-title">{{block.title}}</view><view class="hero-desc">{{block.subtitle}}</view></view></view>
      <view v-else-if="block.type==='activity'" class="activity" :style="{background:block.background||'#fff5e9'}" @click="go('/pages/points/activity')"><view class="activity-icon">🎁</view><view class="activity-main"><view class="title-row"><text class="activity-title">{{block.title}}</text><text class="orange">{{currentPoints}}/{{exchangeScore}}</text></view><view class="progress"><view class="progress-in" :style="{width:pointsProgress+'%'}"/></view><view class="sub activity-sub">邀请好友审核通过，积分自动到账</view></view><view class="activity-btn">{{block.button||'立即查看'}}</view></view>
      <view v-else-if="block.type==='grid'" class="dynamic-section"><view class="section-title">{{block.title}}</view><view class="grid" :style="{gridTemplateColumns:`repeat(${block.columns||3},1fr)`}"><view class="grid-item" v-for="(name,i) in block.items" :key="name" @click="entry({name,url:urlMap[i]||''})"><view class="grid-icon">{{iconMap[i%iconMap.length]}}</view><view class="grid-name">{{name}}</view></view></view></view>
      <view v-else-if="block.type==='study'" class="dynamic-section"><view class="section-title">{{block.title}}</view><view class="card"><view class="title-row"><view><view class="card-title">{{block.title}} 🔥</view><view class="sub">{{block.subtitle}}</view></view><view class="big green">{{block.progress||0}}%</view></view><view class="progress study-progress"><view class="progress-in" :style="{width:(block.progress||0)+'%'}"/></view><view class="divider"/><view class="task"><text>✓ 英语真题训练</text><text class="green">已完成</text></view><view class="task"><text>○ 专业课知识点复习</text><text class="orange">去完成 ›</text></view></view></view>
      <view v-else-if="block.type==='smart'" class="smart-block" :style="{background:block.background||'#dff5ef'}" @click="go('/pages/custom/params')"><view class="smart-icon">✦</view><view class="smart-main"><view class="tag">AI 智能匹配</view><view class="smart-title">{{block.title}}</view><view class="sub">{{block.subtitle}}</view></view><view class="smart-arrow">→</view></view>
      <view v-else-if="block.type==='routes'&&displayRoutes.length" class="dynamic-section"><view class="title-row"><view class="section-title">{{block.title}}</view><text class="sub">{{block.subtitle}}</text></view><scroll-view scroll-x class="route-scroll"><view v-for="route in displayRoutes" :key="route.id||route.name" class="home-route" @click="openRoute(route)"><image :src="route.image" mode="aspectFill"/><view class="home-route-body"><b>{{route.name}}</b><text>{{route.days}} · {{Number(route.price)}} 积分</text></view></view></scroll-view></view>
      <view v-else-if="block.type==='video'" class="dynamic-section"><view class="section-title">{{block.title}}</view><view class="video-card"><image :src="block.image" mode="aspectFill"/><view class="play">▶</view><view class="video-txt">{{block.subtitle}}</view></view></view>
      <view v-else class="notice-block"><b>{{block.title}}</b><text>{{block.subtitle}}</text></view>
    </view>
  </template>
  <template v-else>
    <swiper class="hero" circular autoplay interval="4200" indicator-dots indicator-active-color="#ff7a35"><swiper-item v-for="s in slides" :key="s.title"><view class="hero"><image :src="s.img" mode="aspectFill"/><view class="hero-mask"><view class="tag tag-orange">{{s.kicker}}</view><view class="hero-title">{{s.title}}</view><view class="hero-desc">{{s.desc}}</view></view></view></swiper-item></swiper>
    <view class="activity" @click="go('/pages/points/activity')"><view class="activity-icon">🎁</view><view class="activity-main"><view class="title-row"><text class="activity-title">邀好友赚积分，免费泰山经典游</text><text class="orange">{{currentPoints}}/{{exchangeScore}}</text></view><view class="progress"><view class="progress-in" :style="{width:pointsProgress+'%'}"/></view></view><view class="activity-btn">立即邀请</view></view>
    <view class="section-title">学 · 游一站式服务</view><view class="grid"><view class="grid-item" v-for="(g,i) in fallbackGrids" :key="g.name" @click="entry(g)"><view class="grid-icon">{{iconMap[i]}}</view><view class="grid-name">{{g.name}}</view></view></view>
    <view class="section-title">今日上岸计划</view><view class="card"><view class="card-title">连续打卡 7 天 🔥</view><view class="sub">今天再完成 2 项，离目标更近一步</view></view>
  </template>
 </view><BottomNav active="首页"/>
 <view v-if="showPop" class="mask" @click.self="closePop"><view class="popup"><view class="pop-visual"><text>⛰️</text><view>100 积分 · 泰山见</view></view><view class="pop-body"><view class="pop-title">邀友攒分免费游泰山</view><view class="pop-text">好友扫描专属二维码注册并通过管理员审核后，邀请积分自动到账；满 100 分可兑换 2 天 1 夜泰山全包游。</view><view class="btn btn-primary" @click="invite">立即邀请</view><view class="later" @click="closePop">稍后再说</view></view></view></view>
</view></template>
<script setup>
import{computed,ref,onMounted,onUnmounted}from'vue';import{onShow,onHide,onPullDownRefresh}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import BottomNav from'../../components/BottomNav.vue';import{getInviteDashboard,getPublishedConfig,getPublicRoutes,isLoggedIn,trackPreference}from'../../utils/api.js'
const showPop=ref(false),remoteBlocks=ref([]),remoteRoutes=ref([]),routesLoaded=ref(false),currentPoints=ref(Number(uni.getStorageSync('points')||0)),exchangeScore=ref(100);const iconMap=['📝','📚','🧭','🎁','🪙','🎓','🗺️','✨'];const urlMap=['/pages/study/index','/pages/study/index','/pages/travel/index','/pages/points/activity','/pages/mine/points','/pages/study/center'];const fallbackGrids=[{name:'备考刷题',url:'/pages/study/index'},{name:'资料商城',url:'/pages/study/index'},{name:'定制旅行',url:'/pages/travel/index'},{name:'邀请有礼',url:'/pages/points/activity'},{name:'我的积分',url:'/pages/mine/points'},{name:'上岸权益',url:'/pages/study/center'}];const slides=[{kicker:'上岸限定',title:'备考上岸，全包定制长线旅行',desc:'用一次远行，奖励认真生活的自己',img:'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?w=1200'}];const displayRoutes=computed(()=>routesLoaded.value?remoteRoutes.value:[]);const pointsProgress=computed(()=>Math.min(100,Math.round(currentPoints.value/Math.max(1,exchangeScore.value)*100)))
let refreshTimer=null;const loadHome=async()=>{const tasks=[getPublishedConfig(),getPublicRoutes()];if(isLoggedIn())tasks.push(getInviteDashboard().catch(()=>null));const[config,routes,invite]=await Promise.all(tasks);const home=config?.pages?.find(p=>p.id==='home');if(home)remoteBlocks.value=home.blocks.filter(b=>b.visible);remoteRoutes.value=routes;routesLoaded.value=true;if(invite){currentPoints.value=invite.points;exchangeScore.value=invite.exchange_score;uni.setStorageSync('points',invite.points)}};const startAutoRefresh=()=>{clearInterval(refreshTimer);loadHome();refreshTimer=setInterval(loadHome,3000)};const stopAutoRefresh=()=>{clearInterval(refreshTimer);refreshTimer=null};onMounted(()=>{if(!uni.getStorageSync('welcomeSeen'))setTimeout(()=>showPop.value=true,400)});onShow(startAutoRefresh);onHide(stopAutoRefresh);onUnmounted(stopAutoRefresh);onPullDownRefresh(async()=>{await loadHome();uni.stopPullDownRefresh()})
const go=url=>uni.navigateTo({url});const closePop=()=>{showPop.value=false;uni.setStorageSync('welcomeSeen',true)};const entry=g=>{if(['备考刷题','资料商城'].includes(g.name))trackPreference({type:'study',key:g.name==='备考刷题'?'exam_questions':'materials',name:g.name,action:'entry_click',score:2});g.url?go(g.url):uni.showToast({title:`${g.name}功能演示`,icon:'none'})};const openRoute=route=>{trackPreference({type:'route',key:route.id||route.name,name:route.name,action:'view',score:1});go('/pages/custom/detail')};const invite=()=>{closePop();go('/pages/points/activity')}
</script>
