px;height:78rpx;border-radius:50%;background:rgba(255,255,255,.9);color:#ff7a35;text-align:center;line-height:78rpx}.video-txt{position:absolute;left:24rpx;right:24rpx;bottom:24rpx;color:#fff;font-weight:800}.notice-block{text-align:center;padding:22rpx 20rpx 26rpx;color:#778684}.notice-block b,.notice-block text{display:block}.notice-block text{font-size:22rpx;margin-top:7rpx}.mask{position:fixed;inset:0;background:rgba(9,28,25,.6);z-index:80;display:flex;align-items:center;justify-content:center;padding:48rpx}.popup{width:100%;background:#fff;border-radius:38rpx;overflow:hidden}.pop-visual{height:230rpx;background:linear-gradient(160deg,#0b655d,#20a999);display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-size:28rpx}.pop-visual text{font-size:92rpx}.pop-body{padding:38rpx}.pop-title{text-align:center;font-size:38rpx;font-weight:900}.pop-text{color:#778684;line-height:1.8;margin:20rpx 0 30rpx}.later{text-align:center;color:#899491;padding:24rpx}
</style>
